import { StyleFn } from "..";

export const Progressbar: StyleFn = (theme, mode) => {
  const { color, font, size } = theme;

  return {
    root: {
      display: "flex",
      alignItems: "center",
    },
    percentage: {
      width: size.spacing[40],
      // lineHeight: size.spacing[24],
      marginRight: size.spacing[8],
      textAlign: "right",
      fontSize: font.size.small,
      color: color.text.neutral.default[mode],
      "&$percentage_right": {
        marginRight: 0,
        marginLeft: size.spacing[8],
        textAlign: "left",
      },
    },
    percentage_right: {},
    track: {
      height: size.spacing[8],
      width: "100%",
      overflow: "hidden",
      position: "relative",
      borderRadius: size.spacing[4],
      backgroundColor: color.surface.componentbackground.moderate[mode],
    },
    fill: {
      position: "absolute",
      top: 0,
      bottom: 0,
      borderRadius: size.spacing[4],
      backgroundColor: color.surface.feedback.information.default[mode],
      transition: "width 1s",
    },
    label: {
      fontSize: font.size.small,
      fontWeight: font.weight.regular,
      color: color.text.neutral.default[mode],
      marginBottom: size.spacing[8],
    },
    _indeterminate: {
      "& $fill": {
        width: "50%",
        left: "-50%",
        animation: "$indeterminate 1.5s linear infinite",
      },
    },
    _success: {
      "& $fill": {
        backgroundColor: color.surface.feedback.success.default[mode],
      },
    },
    _warning: {
      "& $fill": {
        backgroundColor: color.surface.feedback.warning.default[mode],
      },
    },
    _error: {
      "& $fill": {
        backgroundColor: color.surface.feedback.error.default[mode],
      },
    },
    "@keyframes indeterminate": {
      from: {
        transform: "translateX(0)",
      },
      to: {
        transform: "translateX(400%)",
      },
    },
  };
};
